css:
/* From Uiverse.io by 1osm - Tags: card */
.__UIV_SCOPE__ .YoutubeVideo {
  width: 250px;
  height: 220px;
  background: transparent;
}

.__UIV_SCOPE__ .Image {
  width: 250px;
  height: 154px;
  border-radius: 10px;
  background: #3a3a3a;
}

.__UIV_SCOPE__ .Icon {
  width: 40px;
  height: 40px;
  border-radius: 100px;
  float: right;
  background-color: #3a3a3a;
  transform: translate(0px,10px);
}

.__UIV_SCOPE__ .Title {
  width: 180px;
  height: 15px;
  border-radius: 2px;
  float: right;
  background-color: #3a3a3a;
  transform: translate(-15px,10px);
}

.__UIV_SCOPE__ .Name {
  width: 100px;
  height: 15px;
  border-radius: 2px;
  float: right;
  background-color: #3a3a3a;
  transform: translate(-15px,20px);
}
